const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('IE 1차 응답 파싱 실패: content 없음');
const parsed = JSON.parse(String(content).replace(/```json|```/g, '').trim());
let categories = parsed.policy_categories || [];
if (!categories.length) throw new Error('policy_categories 배열이 비어 있음');

// 모델이 같은 카테고리를 중복 반환하는 경우 제거 (policy_area > section_no > section_title 순 키)
const seen = new Set();
categories = categories.filter((c) => {
  const key = String(c.policy_area || c.section_no || c.section_title || '').trim().toLowerCase();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});

return categories.map((c) => ({ json: {
  policy_id: 'moamall_2026_05',
  policy_name: parsed.document_title || '모아몰 고객 응대 정책 약관',
  section_no: c.section_no,
  section_id: `sec_${String(c.section_no).padStart(2, '0')}`,
  section_title: c.section_title,
  policy_area: c.policy_area,
  keywords: c.keywords || []
}}));

