const content = $json.choices?.[0]?.message?.content;
if (!content) throw new Error('IE 2차 응답 파싱 실패: content 없음');
const detail = JSON.parse(String(content).replace(/```json|```/g, '').trim());
const rawRules = Array.isArray(detail.rules) ? detail.rules : [];
// 모델이 동일 규칙을 여러 번 반환하는 경우 제거 (rule_name|value|unit|condition 키)
const seenRule = new Set();
const rules = rawRules.filter((r) => {
  const key = `${r.rule_name || ''}|${r.value || ''}|${r.unit || ''}|${r.condition || ''}`.trim();
  if (seenRule.has(key)) return false;
  seenRule.add(key);
  return true;
});
let sec = {};
try { sec = $('섹션 루프').item.json; } catch (e) {}
if (!sec.section_title) {
  const cats = $('섹션 분해').all().map(i => i.json);
  sec = cats.find(c => String(c.section_title || '').trim() === String(detail.section_title || '').trim()) || cats[0] || {};
}
const uniqJoin = (arr, sep = ' / ') => [...new Set((arr || []).filter(Boolean).map(v => String(v).trim()).filter(Boolean))].join(sep);
const amount_rules = rules
  .filter(r => String(r.unit || '').includes('원') || String(r.value || '').includes('원'))
  .map(r => `${r.rule_name}: ${r.value}${r.unit ? ' ' + r.unit : ''}${r.condition ? ' (' + r.condition + ')' : ''}`)
  .join(' / ');
const period_rules = rules
  .filter(r => String(r.unit || '').match(/일|시간|개월|주/) || String(r.value || '').match(/일|시간|개월|주/))
  .map(r => `${r.rule_name}: ${r.value}${r.unit ? ' ' + r.unit : ''}${r.condition ? ' (' + r.condition + ')' : ''}`)
  .join(' / ');
const allowed_conditions = uniqJoin(rules.map(r => r.condition));
const exceptions = uniqJoin(rules.map(r => r.exception).filter(v => v && v !== '없음' && v !== 'N/A'));
const required_evidence = uniqJoin(rules.map(r => r.required_evidence).filter(v => v && v !== '없음' && v !== 'N/A'));
const risky_expressions = uniqJoin([...(detail.risk_keywords || []), ...rules.map(r => r.rule_name)], ', ');
const escalation_conditions = uniqJoin([
  ...(detail.escalation_conditions || []),
  ...rules.map(r => r.exception).filter(v => v && v !== '없음' && v !== 'N/A')
]);
return [{ json: {
  policy_id: sec.policy_id || 'moamall_2026_05',
  policy_name: sec.policy_name || '모아몰 고객 응대 정책 약관',
  section_id: sec.section_id || `sec_${String(detail.section_no || '').padStart(2, '0')}`,
  section_no: sec.section_no || detail.section_no || '',
  section_title: sec.section_title || detail.section_title || '',
  policy_area: sec.policy_area || detail.target_policy_area || '',
  customer_keywords: uniqJoin([...(sec.keywords || []), ...(detail.risk_keywords || [])], ', '),
  required_fields: required_evidence,
  amount_rules,
  period_rules,
  allowed_conditions,
  exceptions,
  required_evidence,
  risky_expressions,
  escalation_conditions,
  safe_reply_guideline: detail.safe_reply_guideline || '',
  source_summary: detail.summary || '',
  created_at: new Date().toISOString()
}}];

return [{ json: {
  success: true,
  message: '정책 구조화 룰셋(18컬럼) 2-pass IE 등록 완료. policy_structured 시트에서 섹션 행 수/컬럼 확인하세요.'
}}];

