let verdict;
try {
  let raw = $('답변 검증 (Solar)').first().json.choices[0].message.content;
  raw = String(raw).replace(/```json/g, '').replace(/```/g, '').trim();
  verdict = JSON.parse(raw);
} catch (e) {
  verdict = { risk_level: 'YELLOW', risk_reason: '검증 응답 파싱 실패: ' + e.message, blocked: false,
    safe_answer: '죄송합니다, 답변을 검증하는 중 문제가 발생했습니다. 상담원에게 연결해 드리겠습니다.' };
}
const merged = $('정책 컨텍스트 조립').first().json;
const risk = (verdict.risk_level || 'YELLOW').toUpperCase();
let policy_source = '';
try { policy_source = $('정책 시트 조회').last().json.source_pdf || ''; } catch (e) {}
const timestamp = new Date().toISOString();
const blocked = risk === 'RED';
let display_answer, show_warning, warning_text;
if (risk === 'RED') {
  show_warning = true;
  warning_text = '정책과 일치하지 않아 답변이 차단되었습니다.';
  display_answer = '안내드린 내용이 최신 정책과 일치하지 않아 표시할 수 없습니다. 정확한 확인을 위해 관리자(상담원)에게 문의해 주세요.';
} else if (risk === 'YELLOW') {
  show_warning = true;
  warning_text = '이 답변은 정책 확인 후 자동 보정된 내용입니다.';
  display_answer = verdict.safe_answer;
} else {
  show_warning = false;
  warning_text = '';
  display_answer = merged.chatbot_answer;
}
return [{ json: {
  customer_name: merged.customer_name,
  customer_question: merged.customer_question,
  chatbot_answer: merged.chatbot_answer,
  risk_level: risk,
  risk_reason: verdict.risk_reason,
  blocked,
  safe_answer: verdict.safe_answer,
  policy_source,
  timestamp,
  _customer: { risk_level: risk, display_answer, show_warning, warning_text, blocked, policy_source, timestamp }
}}];

