parameters.jsCode:
let meta = { topic:'기타', intent:'기타일반문의', sentiment:'중립', urgency:'보통' };
try {
  let raw = $('고객 메타 분류 (Solar)').first().json.choices[0].message.content;
  raw = String(raw).replace(/```json/g,'').replace(/```/g,'').trim();
  const m = JSON.parse(raw);
  meta = {
    topic: m.topic || meta.topic,
    intent: m.intent || meta.intent,
    sentiment: m.sentiment || meta.sentiment,
    urgency: m.urgency || meta.urgency
  };
} catch (e) { /* 기본값 유지 */ }
const base = $('YELLOW/RED만 통과').first().json;
return [{ json: { ...base, ...meta } }];

const TOPIC2CAT = {
  '환불':'refund', '교환':'exchange', '배송':'shipping', '쿠폰':'coupon',
  '신선식품':'fresh_food', '전자제품':'electronics', '의류':'clothing',
  '포인트':'points', '정기배송':'subscription', '파손':'damage'
};
function normalizeAreas(row) {
  const blob = [row.policy_area, row.section_title, row.customer_keywords]
    .map(v => String(v || '').toLowerCase()).join(' ');
  const cats = new Set();
  const has = (...ss) => ss.some(s => blob.includes(s));
  if (has('refund','환불','반품'))            cats.add('refund');
  if (has('exchange','교환'))                 cats.add('exchange');
  if (has('deliver','shipping','ship','배송')) cats.add('shipping');
  if (has('coupon','쿠폰'))                   cats.add('coupon');
  if (has('fresh','food','신선','식품'))       cats.add('fresh_food');
  if (has('electron','전자'))                 cats.add('electronics');
  if (has('cloth','apparel','의류'))          cats.add('clothing');
  if (has('point','포인트','적립'))            cats.add('points');
  if (has('subscri','정기'))                  cats.add('subscription');
  if (has('damage','파손','보상'))             cats.add('damage');
  return [...cats];
}
function toPolicyRef(row) {
  const ref = {
    기간규칙: row.period_rules,
    금액규칙: row.amount_rules,
    허용조건: row.allowed_conditions,
    예외조건: row.exceptions,
    필요증빙: row.required_evidence,
  };
  return Object.fromEntries(Object.entries(ref).filter(([k, v]) => v && String(v).trim()));
}
const ruleRows = $('룰셋 시트 조회1').all().map(i => i.json);
const ruleIndex = {};
const policy_rules = [];
for (const r of ruleRows) {
  const ref = toPolicyRef(r);
  const cats = normalizeAreas(r);
  policy_rules.push({
    policy_id: r.policy_id,
    policy_name: r.section_title || r.policy_name,
    category: cats[0] || r.policy_area || '',
    rules: ref,
    source_pdf: r.source_pdf || r.policy_name || '',
    created_at: r.created_at || ''
  });
  for (const c of cats) {
    if (!ruleIndex[c]) ruleIndex[c] = Object.assign({}, r, { _ref: ref, _name: r.section_title || r.policy_name });
  }
}
function buildAction(topic, riskLevel, matched) {
  if (!matched) {
    return { headline: '관련 정책 미확인 — 상담원 직접 검토 필요',
             steps: ['해당 문의에 매칭되는 정책 섹션이 없습니다. 상담원이 약관 원문을 직접 확인하세요.'],
             policy_ref: null, policy_name: '' };
  }
  const name = matched._name || '';
  const steps = [];
  if (riskLevel === 'RED') {
    steps.push('챗봇 답변이 정책과 불일치하여 고객에게 차단 표시됨. 고객에게 정정 안내를 직접 발송하세요.');
  } else if (riskLevel === 'YELLOW') {
    steps.push('자동 보정 답변이 고객에게 전달됨. 보정 내용이 정책과 맞는지 검수 후 필요시 추가 안내하세요.');
  }
  const pairs = Object.entries(matched._ref).map(([k, v]) => `${k}: ${v}`);
  if (pairs.length) steps.push(`적용 정책 [${name}] 기준값 확인 — ${pairs.join(' / ')}`);
  if (matched.safe_reply_guideline && String(matched.safe_reply_guideline).trim()) {
    steps.push(`안전 답변 기준: ${matched.safe_reply_guideline}`);
  }
  if (matched.escalation_conditions && String(matched.escalation_conditions).trim()) {
    steps.push(`에스컬레이션 조건: ${matched.escalation_conditions}`);
  }
  steps.push('위 기준값과 고객 상황(기간/조건/품목)을 대조하여 처리 가능 여부를 최종 판단하세요.');
  return { headline: `${name} 기준으로 대응`, steps, policy_ref: matched._ref, policy_name: name };
}
const logRows = $('로그 시트 조회1').all().map(i => i.json);
logRows.sort((a, b) => String(b.timestamp || '').localeCompare(String(a.timestamp || '')));
const items = logRows.map(l => {
